import { useCallback, useMemo } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';

import {
  useBffData,
  useMediaQuery,
  usePageFilterApplied,
  usePageFilterStatus,
  useSubFilters,
} from 'hooks';
import { BigNumberSparkLineCardData } from 'pages/components';

import { INNOVATION_PAGE_NAME } from '../../constants';
import type { HowWeDoItSection } from '../components';
import {
  HOW_WE_DO_IT_CONFIG,
  INNOVATION_HOME_BFF_HOW_WE_DO_IT_KEY,
  INNOVATION_HOME_BFF_OVERTIME_TREND_KEY,
  INNOVATION_HOME_BFF_VIEW_ID,
  PERFORMANCE_KPI_MAIN_CARDS_CONFIG,
} from '../constants';

export function useInnovationHomePageData() {
  const isDesktopLarge = useMediaQuery('(min-width: 1440px)');
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { setSubFilterValue } = useSubFilters();
  usePageFilterApplied(INNOVATION_PAGE_NAME);
  const { isLoading: filtersLoading } =
    usePageFilterStatus(INNOVATION_PAGE_NAME);

  const pageData = useBffData({
    id: INNOVATION_HOME_BFF_VIEW_ID,
    kpiGroup: 'innovation',
    skipRequest: filtersLoading,
  });

  const performanceKpiTrendCards = useMemo((): BigNumberSparkLineCardData[] => {
    const trend = pageData?.data?.[INNOVATION_HOME_BFF_OVERTIME_TREND_KEY];
    return Array.isArray(trend) ? trend : [];
  }, [pageData]);

  const mainCardsData = useMemo(() => {
    const findTrend = (legacyTitle: string, shortTitle: string) =>
      performanceKpiTrendCards.find(
        (item) => item.chartTitle === legacyTitle,
      ) ??
      performanceKpiTrendCards.find((item) => item.chartTitle === shortTitle) ??
      null;

    return {
      innovationVolume: findTrend('Innovation Volume', 'Volume'),
      innovationNetRevenue: findTrend('Innovation Net Revenue', 'Net Revenue'),
    };
  }, [performanceKpiTrendCards]);

  const howWeDoItCardsData = useMemo(() => {
    const data = pageData?.data?.[INNOVATION_HOME_BFF_HOW_WE_DO_IT_KEY] as
      | Partial<
          Record<
            (typeof HOW_WE_DO_IT_CONFIG)[number]['dataKey'],
            HowWeDoItSection
          >
        >
      | null
      | undefined;
    return data ?? null;
  }, [pageData]);

  const onKpiClick = useCallback(
    (kpiId: string) => {
      const isNavigable = PERFORMANCE_KPI_MAIN_CARDS_CONFIG.some(
        (card) => card.kpiId === kpiId && card.navigable,
      );
      if (!isNavigable) {
        return;
      }

      setSubFilterValue('kpis', kpiId);
      const newParams = new URLSearchParams(searchParams);
      newParams.set('kpi', kpiId);
      navigate(
        `/innovation/innovation/performance-and-breakdown?${newParams.toString()}`,
      );
    },
    [navigate, searchParams, setSubFilterValue],
  );

  return {
    isDesktopLarge,
    pageData,
    performanceKpiTrendCards,
    mainCardsData,
    howWeDoItCardsData,
    onKpiClick,
  };
}

export type InnovationHomePageDataBundle = ReturnType<
  typeof useInnovationHomePageData
>;
